package ru.neverland.townyquests.cooperative;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.time.*;
import java.time.format.DateTimeFormatter;
import org.bukkit.*;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;
import ru.neverland.townyquests.service.QuestService;

/** Existing paid delivery orders supply cooperative budgets; no separate inventory or monetary mutation. */
public final class CooperativeMenu implements Listener {
    private final JavaPlugin plugin;private final QuestService quests;private final CooperativeService service;private final CooperativeAudit audit;
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm 'МСК'").withZone(ZoneId.of("Europe/Moscow"));
    private static final class View implements InventoryHolder{final UUID player;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;View(UUID player){this.player=player;}public Inventory getInventory(){return inventory;}}
    public CooperativeMenu(JavaPlugin plugin,QuestService quests,CooperativeService service){this.plugin=plugin;this.quests=quests;this.service=service;this.audit=new CooperativeAudit(plugin);plugin.getServer().getPluginManager().registerEvents(this,plugin);}
    private boolean admin(CommandSender p){return p.isOp()||p.hasPermission("neverlandtownyquests.admin");}
    private boolean allowed(Player p){return p.hasPermission("neverlandtownyquests.use")&&!SuiteState.frozen(plugin.getName());}
    private View view(Player p,String title){if(!allowed(p))throw new IllegalArgumentException("Нет доступа к общим стройкам");var v=new View(p.getUniqueId());v.inventory=MenuStyle.inventory(plugin,v,54,title);button(v,49,Material.CLOCK,"Загружаем данные",List.of("Ресурсы учитываются после подтверждения склада."),null);p.openInventory(v.inventory);return v;}
    private boolean current(Player p,View v){return p.isOnline()&&allowed(p)&&p.getOpenInventory().getTopInventory()==v.inventory;}
    private <T>void render(Player p,View v,CompletionStage<T> job,Consumer<T> draw){job.whenComplete((value,error)->{if(!plugin.isEnabled())return;SuiteScheduler.entity(plugin,p,()->{if(!current(p,v))return;v.inventory.clear();v.actions.clear();if(error!=null){button(v,22,Material.BARRIER,"Сведения временно недоступны",List.of(failure(error),"Прежние проекты и вклады сохранены."),null);button(v,48,Material.ARROW,"К общим стройкам",List.of(),()->home(p,1));return;}try{draw.accept(value);}catch(RuntimeException bad){button(v,22,Material.BARRIER,"Нужна проверка данных",List.of("Обратитесь к администрации; вклады не изменены."),null);}});});}
    private static String failure(Throwable e){while(e.getCause()!=null&&(e instanceof CompletionException||e instanceof java.lang.reflect.InvocationTargetException))e=e.getCause();return e.getMessage()==null?"Нет связи со складом":e.getMessage();}
    private void button(View v,int slot,Material icon,String title,List<String> lore,Runnable action){var item=new ItemStack(icon);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("§b"+title));meta.setLore(MenuStyle.loreStrings(lore.stream().map(s->"§7"+s).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);v.inventory.setItem(slot,item);if(action!=null)v.actions.put(slot,action);}
    private void material(View v,int slot,String key,long need,long funded){Material type=Material.matchMaterial(key);if(type==null||!type.isItem())type=Material.PAPER;var item=new ItemStack(type);var meta=item.getItemMeta();meta.displayName(net.kyori.adventure.text.Component.translatable(type.translationKey()).decoration(net.kyori.adventure.text.format.TextDecoration.ITALIC,false));meta.setLore(MenuStyle.loreStrings(List.of("§7Нужно: "+need,"§7Подтверждено в резерве: "+funded,"§7Осталось: "+Math.max(0,need-funded))));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);v.inventory.setItem(slot,item);}
    public void home(Player p,int page){var v=view(p,"Общие стройки городов");render(p,v,service.projects(page),rows->{int slot=0;for(var r:rows){String id=(String)r.get("id");button(v,slot++,Material.BRICKS,(String)r.get("title"),List.of(status((String)r.get("state")),r.get("scope").equals("CITY")?"Городской проект с общей помощью":"Общесерверная стройка",Boolean.TRUE.equals(r.get("funded"))?"Все материалы подтверждены":"Сбор материалов продолжается","Нажмите: смета и доступные поставки"),()->project(p,id,0));}button(v,45,Material.ARROW,"Назад",List.of("Страница "+page),page>1?()->home(p,page-1):()->p.performCommand("town quests"));button(v,47,Material.WRITABLE_BOOK,"Мой городской вклад",List.of("Подтверждённые поставки города","Город закрепляется при начале передачи"),()->receipts(p,1));button(v,49,Material.SUNFLOWER,"Обновить",List.of("Только подтверждённые данные склада"),()->home(p,page));button(v,51,Material.CRAFTING_TABLE,"Начать общую стройку",List.of("Городскую смету создаёт мэр","Серверную — администратор"),()->templates(p,0));if(rows.size()==20)button(v,53,Material.ARROW,"Далее",List.of(),()->home(p,page+1));});}
    @SuppressWarnings("unchecked")public void project(Player p,String id,int page){var v=view(p,"Смета общей стройки");render(p,v,service.project(id),r->{if(r.isEmpty())throw new IllegalArgumentException("Проект не найден");var needs=new TreeMap<>((Map<String,Long>)r.get("needs"));var credited=(Map<String,Long>)r.get("credited");int pages=Math.max(1,(needs.size()+35)/36),at=Math.max(0,Math.min(page,pages-1));int slot=0;for(var e:needs.entrySet().stream().skip(at*36L).limit(36).toList())material(v,slot++,e.getKey(),e.getValue(),credited.getOrDefault(e.getKey(),0L));button(v,40,Material.BOOK,(String)r.get("title"),List.of(status((String)r.get("state")),"Зачёт города: от "+r.get("minimumCredit")+" единиц",r.get("scope").equals("CITY")?"Отметку получит город, начавший стройку":"Отметку получат города, достигшие порога","Материалы берутся из оплаченных /orders.","За сам проект второй выплаты нет.","Физическую стройку завершает администратор."),null);button(v,45,Material.ARROW,at>0?"Предыдущие материалы":"Общие стройки",List.of(),at>0?()->project(p,id,at-1):()->home(p,1));button(v,47,Material.CHEST,"Направить мой заказ",List.of("Выберите уже принятый заказ доставки.","Списываются его обычные материалы.","Награда и лимиты заказа не меняются.","Избыток уйдёт в общий серверный запас."),r.get("state").equals("OPEN")?()->orders(p,id):null);button(v,49,Material.SUNFLOWER,"Обновить",List.of(),()->project(p,id,at));button(v,51,Material.WRITABLE_BOOK,"История и завершение",List.of("Кто создал, завершил или отменил смету"),()->history(p,id));if(at+1<pages)button(v,53,Material.ARROW,"Следующие материалы",List.of(),()->project(p,id,at+1));});}
    private void orders(Player p,String project){var v=view(p,"Поставки для общей стройки");try{var rows=service.orders(p);v.inventory.clear();int slot=0;for(var row:rows){UUID id=UUID.fromString((String)row.get("id"));String title=(String)row.get("title");button(v,slot++,Material.CHEST,title,List.of("Материалов: "+row.get("goal"),"Обычная награда заказа: "+AuditTrail.cents(((Number)row.get("cents")).longValue()),"Нажмите: проверить подтверждение"),()->confirmDelivery(p,project,id,title,((Number)row.get("goal")).intValue()));}if(rows.isEmpty())button(v,22,Material.BOOK,"Нет принятых заказов доставки",List.of("Выберите подходящий заказ в /orders.","Задания на добычу и охоту сюда не подходят."),null);button(v,45,Material.ARROW,"К смете",List.of(),()->project(p,project,0));button(v,49,Material.CHEST,"Открыть /orders",List.of("Примите нужный заказ доставки"),()->p.performCommand("orders"));}catch(Exception e){v.inventory.clear();button(v,22,Material.BARRIER,"Поставки недоступны",List.of(failure(e)),null);}}
    private void confirmDelivery(Player p,String project,UUID order,String title,int amount){var v=view(p,"Подтверждение поставки");v.inventory.clear();button(v,13,Material.CHEST,title,List.of("Передать материалов: "+amount,"Город закрепится при начале передачи.","Недостающее попадёт в резерв стройки.","Избыток — в общий запас сервера.","Награда заказа остаётся прежней."),null);button(v,20,Material.LIME_DYE,"Передать материалы",List.of("Нажмите один раз и дождитесь результата"),()->{if(v.actions.remove(20)==null)return;button(v,20,Material.CLOCK,"Передаём материалы",List.of("Не повторяйте действие до ответа склада"),null);service.deliver(p,order,project).whenComplete((ignored,error)->{if(!plugin.isEnabled())return;SuiteScheduler.entity(plugin,p,()->{if(!p.isOnline())return;p.sendMessage(error==null?"§aПоставка обработана. Подтверждённый вклад смотрите в истории города; избыток остаётся в серверном запасе.":"§e"+failure(error));if(current(p,v))project(p,project,0);});});});button(v,24,Material.ARROW,"Вернуться",List.of("Материалы пока не переданы"),()->orders(p,project));}
    private void templates(Player p,int page){var v=view(p,"Сметы общих строек");v.inventory.clear();int slot=0;for(var t:service.templates().values().stream().sorted(Comparator.comparing(CooperativeService.Template::id)).skip(page*45L).limit(45).toList())button(v,slot++,Material.CRAFTING_TABLE,t.title(),List.of(t.scope().equals("SERVER")?"Серверный проект; создаёт администратор":"Городской проект; создаёт мэр", "Материалов в смете: "+t.needs().size(),"Нажмите: создать неизменяемую смету"),()->{try{plan(p,t.id());}catch(Exception e){p.sendMessage("§e"+failure(e));}});if(page>0)button(v,45,Material.ARROW,"Предыдущая страница",List.of(),()->templates(p,page-1));if((page+1)*45<service.templates().size())button(v,53,Material.ARROW,"Следующая страница",List.of(),()->templates(p,page+1));button(v,49,Material.ARROW,"К общим стройкам",List.of(service.issue().isEmpty()?"Существующие сметы сохраняют условия":service.issue()),()->home(p,1));}
    private void receipts(Player p,int page){var town=quests.town(p);if(town==null)throw new IllegalArgumentException("Для истории городского вклада нужен свой город");UUID id=town.getUUID();var v=view(p,"Вклад города в стройки");render(p,v,service.receipts(id,page),rows->{var currentTown=quests.town(p);if(currentTown==null||!currentTown.getUUID().equals(id)){p.closeInventory();return;}int slot=0;for(var row:rows){Material material=Material.matchMaterial((String)row.get("material"));button(v,slot++,material==null?Material.PAPER:material,"Поставка: "+row.get("amount"),List.of("Стройка: "+row.get("project"),"Состояние резерва: "+allocation((String)row.get("state")),DATE.format(Instant.ofEpochMilli(((Number)row.get("at")).longValue())),"Квитанция: "+row.get("delivery")),null);}button(v,45,Material.ARROW,page>1?"Предыдущая страница":"Общие стройки",List.of(),page>1?()->receipts(p,page-1):()->home(p,1));button(v,49,Material.SUNFLOWER,"Обновить",List.of(),()->receipts(p,page));if(rows.size()==20)button(v,53,Material.ARROW,"Далее",List.of(),()->receipts(p,page+1));});}
    private void history(Player p,String id){var v=view(p,"История общей стройки");render(p,v,service.history(id),rows->{int slot=0;for(var row:rows)button(v,slot++,Material.WRITABLE_BOOK,(String)row.get("actor"),List.of(status((String)row.get("action")),(String)row.get("reason"),DATE.format(Instant.ofEpochMilli(((Number)row.get("at")).longValue()))),null);button(v,45,Material.ARROW,"К смете",List.of(),()->project(p,id,0));if(admin(p)){button(v,48,Material.LIME_DYE,"Завершить после проверки стройки",List.of("Материалы должны быть подтверждены.","Нужна команда с основанием проверки."),()->p.sendMessage("§e/t quests joint complete "+id+" confirm <что построено и проверено>"));button(v,50,Material.RED_DYE,"Отменить без провала",List.of("Резерв вернётся в серверный запас.","Игроки уже получают награды заказов."),()->p.sendMessage("§e/t quests joint cancel "+id+" confirm <основание отмены>"));}});}
    private void plan(CommandSender sender,String template){var t=service.templates().get(template);if(t==null)throw new IllegalArgumentException("Смета не найдена");UUID city=null;if(t.scope().equals("CITY")){if(!(sender instanceof Player p))throw new IllegalArgumentException("Городскую смету создают в игре");var town=quests.town(p);if(town==null||!admin(p)&&!town.isMayor(com.palmergames.bukkit.towny.TownyAPI.getInstance().getResident(p)))throw new IllegalArgumentException("Городскую смету создаёт мэр своего города");city=town.getUUID();}else if(!admin(sender))throw new IllegalArgumentException("Серверную смету создаёт администратор");result(sender,service.plan(t,city,sender.getName()),"PLAN");}
    private void result(CommandSender sender,CompletionStage<Map<String,Object>> job,String action){final AuditRecord.Party actor;try(var guard=SuiteState.guard()){actor=sender instanceof Player p?AuditTrail.player(p.getUniqueId()):new AuditRecord.Party("CONSOLE","",sender.getName(),"");}audit.track(job,action,actor);sender.sendMessage("§eСохраняем операцию общей стройки…");job.whenComplete((row,error)->{if(!plugin.isEnabled())return;SuiteScheduler.reply(plugin,sender,()->{if(error!=null){sender.sendMessage("§e"+failure(error));return;}sender.sendMessage("§aСтройка «"+row.get("title")+"»: "+status((String)row.get("state"))+". ID: "+row.get("id"));});});}
    public void command(CommandSender sender,String[] args){if(SuiteState.frozen(plugin.getName())||sender instanceof Player p&&!allowed(p))throw new IllegalArgumentException("Общие стройки недоступны");if(args.length==0){if(!(sender instanceof Player p))throw new IllegalArgumentException("В игре: /t quests joint; из консоли: joint plan|complete|cancel");home(p,1);return;}switch(args[0].toLowerCase(Locale.ROOT)){case "plan"->{if(args.length!=2)throw new IllegalArgumentException("/t quests joint plan <смета>");plan(sender,args[1]);}case "complete","cancel"->{if(!admin(sender))throw new IllegalArgumentException("Нужны права администратора");if(args.length<4||!args[2].equals("confirm"))throw new IllegalArgumentException("/t quests joint "+args[0]+" <проект> confirm <основание>");String reason=String.join(" ",Arrays.copyOfRange(args,3,args.length));result(sender,service.finish(args[1],args[0].equals("cancel"),sender.getName(),reason),args[0].equals("cancel")?"CANCELLED":"COMPLETED");}case "info"->{if(args.length!=2||!(sender instanceof Player p))throw new IllegalArgumentException("В игре: /t quests joint info <проект>");project(p,args[1],0);}default->throw new IllegalArgumentException("/t quests joint [plan|info|complete|cancel]");}}
    private static String status(String state){return switch(state){case "OPEN"->"Собираем материалы";case "COMPLETED"->"Завершено";case "CANCELLED"->"Отменено без провала";case "PLAN"->"Создана смета";default->state;};}private static String allocation(String state){return switch(state){case "RESERVED"->"Сохранено для стройки";case "SPENT"->"Использовано в стройке";case "RETURNED"->"Возвращено в серверный запас";default->state;};}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder()instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked()instanceof Player p)||!v.player.equals(p.getUniqueId()))return;if(!allowed(p)){p.closeInventory();return;}var action=v.actions.get(e.getRawSlot());if(action!=null)SuiteScheduler.entity(plugin,p,()->{if(!current(p,v))return;try{action.run();}catch(Exception error){p.sendMessage("§e"+failure(error));}});}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder()instanceof View)e.setCancelled(true);}
    public CompletionStage<Void> closeAsync(){return audit.closeAsync();}
    public void close(){SuiteScheduler.cleanupPlayers(plugin,p->{if(p.getOpenInventory().getTopInventory().getHolder()instanceof View)p.closeInventory();});}
}
